function frameworkById(id) {
  return FRAMEWORKS.find(f => f.id === id) ?? FRAMEWORKS[0];
}
function eraStages(s) {
  const f = frameworkById(s.era?.frameworkId);
  return (f.implemented ? f : FRAMEWORKS[0]).stages;
}
function stageOf(s) {
  const stages = eraStages(s);
  return stages[Math.min(s.era?.index ?? 0, stages.length - 1)];
}
function frameworkUnlockStage(frameworkId, courseId) {
  const f = frameworkById(frameworkId);
  if (!f.implemented) return 0;
  const i = f.stages.findIndex(st => st.courses.includes(courseId));
  return i < 0 ? 0 : i;
}
