// core/bridge.ts
var rules = {
  ...meta_default,
  ...parameters_default,
  ...legacy_default,
  ...systems_default,
  scenarios: scenarios_default,
  catalogs: catalogs_default
};
var FarmCore = class {
  constructor() {
    this.busy = false;
  }
  async start(saved) {
    this.session = saved ? parseSession(JSON.parse(saved)) : await createSession({
      runId: "cocos-farm",
      ruleset: rules,
      seed: 270927,
      frameworkId: "riverine"
    });
    return this.observe();
  }
  observe() {
    return observeSession(this.session);
  }
  save() {
    return JSON.stringify(this.session);
  }
  async act(id) {
    if (this.busy) throw new Error("\u4E0A\u4E00\u9879\u519C\u4E8B\u5C1A\u672A\u5B8C\u6210");
    this.busy = true;
    try {
      const revision = this.session.record.entries.length;
      const result = await submitCommand(this.session, {
        commandId: `phone:${revision}:${id}`,
        expectedRevision: revision,
        actionId: id
      });
      this.session = result.session;
      return this.observe();
    } finally {
      this.busy = false;
    }
  }
};
export { FarmCore };